      "બે બ્રાહ્મણોએ નિયમ લીધો કે બાર મહિના નદીમાં નાહવું. ઉનાળો - ચોમાસું તો બરોબર ચાલ્યું પણ જ્યાં આકરો શિયાળો આવ્યો ત્યારે કઠણ પડવા માંડ્યું. એક દિવસ ખૂબ ટાઢ પડેલી. હિમ પડી ગયેલું.",
