      "એક મસ્જિદમાં મુસલમાનો નમાજ પઢવા ભેગા થયા હતા. મસ્જિદમાં ભીડ ઘણી જ હતી. તેમાં એક જણ પડી ગયો. તે ઊભો થવા ગયો ત્યાં પડખેવાળાને તેની કોણી વાગી ગઈ. તેણે બીજાને કોણી મારી.",
