    "estimatedMinutes": 2,
    "content": [
      "એક અવળચંડી બાઈ હતી. તે ધણી કહે તેમ ન કરે. પણ તેથી ઊંધું જ કરે. ખાટલો પાથરવાનું કહે તો ઊંધો ખાટલો પાથરે ! પાણી માગે તો પથરો ધરે ! ધણી આ બાઈથી કંટાળી ગયો હતો. આ પાપમાંથી તેને છૂટવું હતું.",
      "એકવાર તેઓ બંને નદી ઊતરતાં હતાં. નદીમાં પૂર હતું તેથી બાઈએ ભેંસનું પૂછડું પકડી રાખેલું. ધણીને તો આને વહેતી મૂકી દેવી હતી. તેથી તેણે કહ્યું : 'બરાબર પૂછડું ઝાલજો.' ધણી કહે તેનાથી અવળું કરનારી આ અવળચંડી બાઈ ભેંસનું પૂછડું મૂકી દેતાં બોલી : 'આ મૂક્યું !' અને પાણીના પૂરમાં તણાઈ ગઈ. તે ગઈ ખંભાતને ખાળે."
    ],
    "moral": "અવળાઈનું ફળ આવું છે. કહ્યું ન કરે તેમાં રામ રાજી ન થાય. આવા સેવકને શ્રીજીમહારાજ ટૂંકડા આવવા દેતા નથી. પાસે હોય તો દૂર જ કરે. સંત-ભગવાનની આજ્ઞા સવળી રીતે પાળવી."
