    "estimatedMinutes": 3,
    "content": [
      "અંબરીષ રાજા આત્મનિવેદી હતા. તેમણે અને તેમનાં રાણીએ બાર મહિનાની નિર્જળા એકાદશીઓનું વ્રત કર્યું હતું. કારતક સુદ બારસે વ્રતની સમાપ્તિ હતી. બારસની વહેલી સવારે દુર્વાસા તેમના સો શિષ્યોને લઈને અંબરીષ રાજાને ત્યાં પધાર્યા. અંબરીષ રાજા રાજી થયા અને પગે પડી સ્વાગત કરતાં બોલ્યા : 'આજે મારે એકાદશી વ્રતના પારણાં છે. અને તમે મારે બારણે આવ્યા એટલે આજે તો મારાં મોટાં ભાગ્ય. જમવા પધારો !'",
      "દુર્વાસાએ કહ્યું : 'અમે નદીએ નાહીને આવીએ છીએ.' દુર્વાસા અને શિષ્યો નદીએ ગયા. 'ભેંસ, બ્રાહ્મણ ને ભાજી; પાણી દેખીને રાજી.' બધા ખૂબ નાહવા મંડ્યા. આ બાજુ બારસ બેસતી હતી અને પારણાં કરવાનું મુહૂર્ત થતું હતું. બ્રાહ્મણોએ વચલો રસ્તો કાઢ્યો કે 'તમે ભગવાનનું પ્રસાદીનું એક તુલસીપત્ર જમી લ્યો એટલે પારણાં થઈ ગયા કહેવાય.' અંબરીષે તુલસીપત્ર મુખમાં મૂક્યું.",
      "એટલામાં દુર્વાસા આવ્યા. તેમને ખબર પડી કે અંબરીષે પારણાં કરી લીધાં, એટલે ક્રોધમાં આવી પોતાની જટામાંથી કૃત્યા ઉત્પન્ન કરી અંબરીષને મારવા મોકલી. અંબરીષ તો હાથ જોડીને ઊભા રહ્યા. ભગવાને રક્ષામાં સુદર્શન ચક્ર મૂક્યું હતું. ચક્રે કૃત્યાને ભસ્મ કરી અને દુર્વાસા પાછળ પડ્યું.",
      "દુર્વાસા શંકર ભગવાન પાસે ગયા, વિષ્ણુ ભગવાન પાસે ગયા. ભગવાને કહ્યું: 'હું ભક્તને આધીન છું. તમે અંબરીષ પાસે નિર્માની થઈને જાવ.' દુર્વાસા અંબરીષના પગમાં પડ્યા. અંબરીષે સુદર્શન ચક્રની સ્તુતિ કરી પાછું વાળ્યું અને દુર્વાસા સાથે પારણાં કર્યાં."
    ],
    "moral": "ભગવાન પોતાના ભક્તનો દ્રોહ સહન કરી શકતા નથી. માટે ભગવાનના એકાંતિક ભક્તનો દ્રોહ કરવો નહિ. તેમની આગળ નિર્માની થવું તો ભગવાન રાજી થાય.",
