      "એક દી, બહારગામ જવું હતું. દીકરાઓને કહ્યું, 'કાલે તમે પૂજા કરજો.' એમ કહીને ગયો. બીજે દી સાંજે પાછો આવ્યો. દીકરાઓને પૂછ્યું : 'ઓલ્યું કામ (શિવલિંગની પૂજા) તમે કર્યું હતું ને ?' દીકરાઓએ કહ્યું, 'ના.'",
