      "એક રાજાએ દીવાનને કહ્યું : 'આપણે હંસ પાળવા છે.' દીવાને કહ્યું : 'સાહેબ ! સતયુગમાં ધોળા, ત્રેતામાં લીલા, દ્વાપરમાં પીળા અને કળિયુગમાં કાળા હંસ હોય છે. હંસ ખીર ને પૂરી ખાય.' દીવાને કાગડા પકડી પાંજરામાં પૂરી ખીર-પૂરી ખવડાવવા માંડી.",
      "શરદ પૂનમે બગીચામાં સાચા હંસ આવ્યા. સિપાઈએ રાજાને વાત કરી. દીવાને કહ્યું કે કળિયુગમાં કાળા જ હંસ હોય. સાચા હંસે કહ્યું : 'સાહેબ, એક પરીક્ષા કરી લ્યો. સાચા હંસ દૂધ અને પાણી નોખાં કરે.'",
      "પાંચ શેર દૂધ અને પાંચ શેર પાણી ભેગું કર્યું. કાગડાઓને કહ્યું તો કાગડાએ લીંબુ નાખવાની કોશિશ કરી કૂંડી ઊંધી વાળી દીધી. જ્યારે સાચા હંસે ચાંચ બોળી ત્યાં દૂધમાં કોકડા વળી ગયા ને પાણી તરીને નોખું પડી ગયું. હંસે કહ્યું: 'હંસ ચારે યુગમાં સરખા જ હોય છે. સાચા હંસ મોતીનો ચારો ચરે.'",
      "સિદ્ધાંત શું ? મહારાજ છતાં નંદ સાધુ હતા, એ ધોળા હંસ હતા. હવે તો કળિયુગમાં કાળા હંસ ! પણ મહારાજ છતાં જેવા સંતો હતા, તેવા ને તેવા અત્યારે પણ હોવા જોઈએ. દૂધ ને પાણી શું નોખું કરે ? પ્રકૃતિ-પુરુષનું કાર્ય, લોક, ભોગ, દેહ અને મુક્ત, અક્ષરપુરુષોત્તમને તે એક ચાંચ બોળે, ને નોખું કરી દે. જગત નોખું પાડી દે."
