      "તપસ્વીની આવી અનન્ય શ્રદ્ધા જોઈ ભગવાન મોરમુકુટ પહેરીને તરત જ સાક્ષાત્ પ્રગટ થઈ ગયા ! નારદજીએ પૂછ્યું: 'પ્રભુ, આટલાં વર્ષોનો વાયદો હતો ને કેમ અત્યારે જ દર્શન દીધાં ?' ભગવાને કહ્યું: 'નારદજી, આની શ્રદ્ધા તો જુઓ ! શ્રદ્ધાવાળાને વહેલી સાધનની સમાપ્તિ થાય છે.'"
