      "ભમરો અને ગીંગો બે ભાઈબંધ. ભમરાએ ગીંગાને કહ્યું : 'મારા બગીચામાં આવ. ત્યાં ગુલાબ છે, કેતકી છે, મોગરો છે. તું ખુશ થઈ જઈશ. અહીં વિષ્ટામાં શું પડ્યો રહ્યો છું ?' ગીંગો વિષ્ટાની બે ગોળીઓ નાકમાં નાંખી ઊપડ્યો. ગુલાબ પર બેસાડ્યો તોય ગીંગો કહે: 'મને તો મારી જ સુગંધ આવે છે.'",
      "ભમરો સમજી ગયો. તેને હોજમાં નવરાવ્યો. નાકમાં પાણી પેસી જતાં વિષ્ટાની ગોળીઓ નીકળી ગઈ. પછી ગુલાબ પર બેસાડ્યો ત્યારે ગીંગો બોલ્યો: 'અહોહો ! શું ગુલાબની સુગંધ !'",
