      "એક માણસને ભૂત વશ થયું. જે કામ ચીંધે તે પળમાં કરી આવે. કામ પતતાં ભૂત કહે: 'કામ બતાવો નહિતર તમને ખાઈ જાઉં.' માણસ ચિંતામાં પડી સુકાવા માંડ્યો.",
      "એક મહાત્માએ ઉપાય બતાવ્યો: 'ગીરના જંગલમાંથી સો હાથનો વાંસડો આંગણામાં ખોડી દે. જ્યારે કામ ન હોય ત્યારે ભૂતને કહેવું કે વાંસડે ચડ-ઊતર કર.' માણસે તેમ કર્યું. જ્યારે કામ ન હોય ત્યારે ભૂત વાંસડે ચડઊતર કર્યા કરે અને માણસ બચી ગયો.",
      "આપણું મન પણ ભૂત જેવું છે. તેને નવરું રહેવા ન દેવું. ભક્તચિંતામણિ, વચનામૃત, સ્વામીની વાતો વાંચ્યા કરવાં, શાસ્ત્રીજી મહારાજનાં ચરિત્રો સંભાર્યા કરવાં. પછી મન નિર્વાસનિક થઈ જાય."
