      "શેઠ ગયા પછી તેનો મિત્ર આવ્યો. આંધળાએ હીરો બતાવ્યો. મિત્ર ઈર્ષ્યાળુ અને મૂર્ખ હતો. તેણે કહ્યું: 'શેઠ કોઈ દી હીરો ન દે, ઝેરનો કટકો આપ્યો છે.' તેણે પડિયામાંથી ગોળ ચટાડ્યો. આંધળાને ગોળ ગળ્યો લાગ્યો અને હીરો ચટાડ્યો તો જીભ તોટી વળી ગઈ. મિત્રએ કહ્યું: 'જોયું ? આ ઝેરનો કટકો છે, સાત કોશી વાવમાં નાખી દે.' આંધળાએ લાખ રૂપિયાનો હીરો વાવમાં ફેંકી દીધો.",
      "શેઠ પાછા આવ્યા ત્યારે આંધળાને રડતો જોયો. આખી વાત જાણી શેઠે પચીસ હજાર રૂપિયા ખર્ચી, કોસ જોડી આખી વાવ ઉલેચાવી હીરો પાછો કઢાવ્યો.",
